sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {

    //MSSCUSTODY-4911
    var host = g_scratchpad.host;
    var dynamic_query = g_scratchpad.query;
    var trade_tt = g_form.getValue('trade_task_type');
    var user_access = g_scratchpad.usr_access;
    var user_was_maker = g_scratchpad.hasWorkedAsMaker;

    if (isLoading || newValue === '') {
        return;
    }

    if (user_was_maker && trade_tt == 'Checker') {
        return;
    } else if (user_access && (trade_tt == 'Maker' || trade_tt == 'Checker')) {
        if (g_form.getValue('assigned_to') != '') {
            if ((newValue == '') || (newValue == g_user.userID)) {
                // do nothing
            } else {
                // alert('Task is now assigned to ' + g_form.getDisplayBox('assigned_to').value);
                // var url = host + '/x_hsb11_mss_c_proc_mss_custody_task_list.do?&sysparm_query=' + dynamic_query;	//Redirects to list view
                // //var url = host + "x_hsb11_mss_c_proc_mss_custody_task_list.do?&sysparm_query=active=true^";
                // top.window.location = url;

				//MSSCUDTODY-6652
                var ans = confirm('Task is now assigned to ' + g_form.getDisplayBox('assigned_to').value);
                if (!ans) {
                    g_form.setValue('assigned_to', oldValue);
                    return;
                } else {
                    var ga = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyBulkUtils'); //Scriptinclude
                    ga.addParam('sysparm_name', 'updateAssignedTo'); //Method
                    ga.addParam('sysparm_sysid', g_form.getUniqueValue());
                    ga.addParam('sysparm_field', 'assigned_to');
					ga.addParam('sysparm_value', newValue);
					ga.getXMLAnswer(function(response){
						if(response === 'success'){
							var url = host + '/x_hsb11_mss_c_proc_mss_custody_task_list.do?&sysparm_query=' + dynamic_query;
							top.window.location = url;
						}else{
							g_form.setValue('assigned_to', oldValue);
							alert("Could not update the assignee");
						}						
					});
                }
            }
        }
    } else {
        return;
    }

}
